<?php
/** Plugin Name: TEMP PS S1721i deploy: petshop-dydziai v2.0 + petshop-dydziai-kortele v1.0 + pilotas (Exclusion seima). 1 lint/sausas, 2 rasyti+heartbeat, 3 pilotas+testai, 9 atstatyti */
add_action('wp_loaded', function(){
  if(!isset($_GET['ps_s1721i'])) return; $f=$_GET['ps_s1721i']; $r=['v'=>'S1721i','faze'=>$f]; @set_time_limit(150);
  $mu=WPMU_PLUGIN_DIR; $bak=dirname(ABSPATH).'/ps-archyvas/';
  $F=['petshop-dydziai.php'=>['b64'=>'','md5'=>'1c4a8ce9ed380b177461cf01bc75c00c'],'petshop-dydziai-kortele.php'=>['b64'=>'','md5'=>'82100fae008c85cae5221c48fc8aad0c']];
  $PILOT=['seima'=>'exclusion-hypo-mazu-kiauliena','ids'=>[18584,18590,36002,18587,36003]];
  $ua=['timeout'=>25,'sslverify'=>false,'user-agent'=>'Mozilla/5.0 ps-s1721','cookies'=>['ps_js'=>'1']];
  try{
  if($f==='1'||$f==='2'){
    foreach($F as $fn=>$x){ $code=base64_decode($x['b64']); $r[$fn]=['md5_ok'=>md5($code)===$x['md5'],'md5_gyvas'=>is_file("$mu/$fn")?md5_file("$mu/$fn"):'NERA','kb'=>round(strlen($code)/1024,1)];
      try{ token_get_all($code, TOKEN_PARSE); $r[$fn]['lint']='ok'; }catch(Throwable $e){ $r[$fn]['lint']='KLAIDA '.$e->getMessage(); } }
    if($f==='2'){ foreach($F as $fn=>$x){ if($r[$fn]['lint']!=='ok'||!$r[$fn]['md5_ok']) $r['STOP']=$fn; }
      if(empty($r['STOP'])){ foreach($F as $fn=>$x){ if(is_file("$mu/$fn")&&!file_exists($bak.$fn.'.bak_s1721')) copy("$mu/$fn",$bak.$fn.'.bak_s1721'); file_put_contents("$mu/$fn",base64_decode($x['b64'])); $r[$fn]['irasyta']=md5_file("$mu/$fn"); }
        $hb=wp_remote_get(home_url('/?ps_hb='.time()),$ua); $c=is_wp_error($hb)?0:wp_remote_retrieve_response_code($hb); $r['heartbeat']=$c;
        if($c>=500||$c===0){ foreach($F as $fn=>$x){ if(file_exists($bak.$fn.'.bak_s1721')) copy($bak.$fn.'.bak_s1721',"$mu/$fn"); else @unlink("$mu/$fn"); } $r['ATSTATYTA']='heartbeat '.$c; } } }
  }
  if($f==='3'){
    // pilotas: seima 5 prekems (bak opcija)
    $b=get_option('ps_s1721_pilot_bak'); if(!is_array($b)){ $b=[]; foreach($PILOT['ids'] as $id) $b[$id]=get_post_meta($id,'_ps_dydzio_seima',true); update_option('ps_s1721_pilot_bak',$b,false); }
    foreach($PILOT['ids'] as $id){ update_post_meta($id,'_ps_dydzio_seima',$PILOT['seima']); $r['seima'][$id]=get_post_meta($id,'_ps_dydzio_seima',true).' | '.Petshop_Dydziai::uzrasas($id).' | '.json_encode(Petshop_Dydziai::kg(Petshop_Dydziai::uzrasas($id))); }
    foreach(['ps_dk_'.md5($PILOT['seima'])] as $tk) delete_transient($tk);
    $r['eilutes']=array_map(function($x){ return $x['id'].' '.$x['uzr'].' '.$x['kaina'].' kg'.$x['kg'].' perkg'.round($x['perkg'],2).' sut'.$x['sutaupai'].' best'.(int)$x['geriausia'].' pop'.(int)$x['perkamiausias'].' pard'.$x['pard']; }, Petshop_Dydziai::eilutes($PILOT['seima'],18590));
    // kesas
    foreach($PILOT['ids'] as $id){ if(function_exists('wp_cache_post_change')) wp_cache_post_change($id); }
    if(class_exists('Petshop_Cache')){ foreach($PILOT['ids'] as $id) Petshop_Cache::preke_id($id); Petshop_Cache::vykdyti(); }
    // testai
    $rs=wp_remote_get(get_permalink(18590).'?ps_nocache='.time(),$ua); $h=wp_remote_retrieve_body($rs); $r['preke']=['code'=>wp_remote_retrieve_response_code($rs),'ps_pak'=>substr_count($h,'class="ps-pak__r'),'2x2'=>strpos($h,'2 × 2 kg')!==false,'pop'=>strpos($h,'perkamiausias')!==false,'best'=>strpos($h,'geriausia kaina už kg')!==false,'pos_pak'=>strpos($h,'id="ps-pak"'),'pos_stock'=>strpos($h,'class="stock in-stock"'),'pos_excerpt'=>strpos($h,'product-short-description')];
    if(($i=strpos($h,'id="ps-pak"'))!==false) $r['preke_html']=substr(preg_replace('/\s+/',' ',substr($h,$i,3000)),0,1600);
    $rs=wp_remote_get(home_url('/kategorija/sunims/maistas-sunims/sausas-maistas-sunims/?ps_nocache='.time()),$ua); $h=wp_remote_retrieve_body($rs); $r['kat']=['code'=>wp_remote_retrieve_response_code($rs),'ps_dk'=>substr_count($h,'class="ps-dk"'),'chips'=>substr_count($h,'ps-dk__ch ')+substr_count($h,'ps-dk__ch"'),'js'=>strpos($h,'ps-dk__ch--sel,.ps-dk__ch--sel:hover')!==false];
    if(($i=strpos($h,'class="ps-dk"'))!==false) $r['kat_html']=substr(preg_replace('/\s+/',' ',substr($h,$i-200,1400)),0,1400);
    $rs=wp_remote_get(home_url('/?ps_dydziai_dienos=18590&w=8'),$ua); $r['dienos']=substr(wp_remote_retrieve_body($rs),0,600);
    $r['heartbeat']=wp_remote_retrieve_response_code(wp_remote_get(home_url('/?ps_hb='.time()),$ua));
    $lf=ini_get('error_log'); if($lf&&is_file($lf)){ $sz=filesize($lf); $h2=fopen($lf,'r'); fseek($h2,max(0,$sz-4000)); $r['log_uodega']=array_slice(array_filter(explode("\n",stream_get_contents($h2))),-4); fclose($h2); }
  }
  if($f==='9'){ foreach($F as $fn=>$x){ if(file_exists($bak.$fn.'.bak_s1721')){ copy($bak.$fn.'.bak_s1721',"$mu/$fn"); $r[$fn]='atstatyta'; } else { @unlink("$mu/$fn"); $r[$fn]='pasalinta'; } }
    $b=get_option('ps_s1721_pilot_bak'); if(is_array($b)){ foreach($b as $id=>$v){ if($v==='') delete_post_meta((int)$id,'_ps_dydzio_seima'); else update_post_meta((int)$id,'_ps_dydzio_seima',$v); } $r['pilotas']='atstatyta'; } }
  }catch(Throwable $e){ $r['FATAL']=$e->getMessage().' @'.$e->getLine(); }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($r,JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit;
}, 1);
